193	.is-block-reveal {
194	  opacity: 0;
195	  visibility: hidden;
196	  transform: translate3d(0, var(--block-reveal-offset-y), 0);
197	  filter: blur(var(--block-reveal-blur));
198	  pointer-events: none;
199	  transition:
200	    opacity var(--transition-slow),
201	    transform var(--transition-slow),
202	    filter var(--duration-default) var(--ease-default),
203	    visibility 0s linear var(--duration-slow);
204	  will-change: transform, opacity, filter;
205	  transform-origin: 50% 100%;
206	  backface-visibility: hidden;
207	
208	  &.is-block-reveal-up {
209	    opacity: 1;
210	    visibility: visible;
211	    transform: translate3d(0, 0, 0);
212	    filter: blur(0);
213	    pointer-events: auto;
214	    transition-delay: 0s, 0s, 0s, 0s;
215	  }
216	
217	  &.is-block-reveal-down {
218	    opacity: 0;
219	    visibility: visible;
220	    transform: translate3d(0, var(--block-reveal-offset-y), 0);
221	    filter: blur(var(--block-reveal-blur));
222	    pointer-events: none;
223	    transition:
224	      opacity var(--transition-slow),
225	      transform var(--transition-slow),
226	      filter var(--duration-default) var(--ease-default),
227	      visibility 0s linear var(--duration-slow);
228	  }
229	
230	  &.is-block-reveal-hidden,
231	  &.is-block-reveal-instant {
232	    transition: none;
233	    opacity: 0;
234	    visibility: hidden;
235	    transform: translate3d(0, var(--block-reveal-offset-y), 0);
236	    filter: blur(var(--block-reveal-blur));
237	    pointer-events: none;
238	  }
