277	    );
278	    --corner-panel-hover-offset-y: 0px;
279	    --corner-panel-corner-hover: var(--clr-text-desc);
280	    --corner-btn-border: var(--corner-panel-border);
281	    --corner-btn-bg: var(--corner-panel-background);
282	    --corner-btn-corner: var(--corner-panel-corner);
283	    --corner-btn-hover-border: var(--corner-panel-border-hover);
284	    --corner-btn-hover-bg: var(--corner-panel-background-hover);
285	    --corner-btn-hover-corner: var(--corner-panel-corner-hover);
286	    display: flex;
