288	    min-height: 100%;
289	    align-items: stretch;
290	    justify-content: flex-start;
291	    padding: var(--corner-panel-padding);
292	    cursor: default;
293	    text-align: left;
294	    transition:
295	      border-color var(--transition-default),
296	      background var(--transition-default),
297	      box-shadow var(--transition-default),
